// Code node "Read the signup". Takes {email, name} from the webhook body and flags free mail domains.
const FREE = /^(gmail|googlemail|yahoo|hotmail|outlook|live|icloud|me|aol|proton|protonmail|gmx|mail|yandex|zoho)\./i;
const body = $input.first().json.body || $input.first().json;
const email = String(body.email || "").trim().toLowerCase();
const domain = email.includes("@") ? email.split("@")[1] : "";
return [{
  json: {
    email,
    name: String(body.name || body.full_name || "").trim(),
    domain,
    work_email: Boolean(domain) && !FREE.test(domain),
    received_at: new Date().toISOString(),
  },
}];

// Code node "Score and route". Turns the agent's verdict into a tier and a Slack line.
// Shared helper: adds up what the agent's looot calls cost, from the agent's intermediate steps
// (the agent's "Return Intermediate Steps" option is on). Each looot tool answer carries actualCost.
function agentCost(item) {
  const steps = (item && Array.isArray(item.intermediateSteps)) ? item.intermediateSteps : [];
  let usd = 0;
  let calls = 0;
  for (const step of steps) {
    const tool = String((step && step.action && step.action.tool) || "");
    if (!/looot/i.test(tool)) continue;
    calls += 1;
    const text = typeof step.observation === "string" ? step.observation : JSON.stringify(step.observation ?? "");
    for (const m of text.matchAll(/"actualCost"\s*:\s*([0-9.eE+-]+)/g)) {
      const n = Number(m[1]);
      if (Number.isFinite(n)) usd += n;
    }
  }
  return { looot_calls: calls, looot_cost_usd: Number(usd.toFixed(6)) };
}

const HOT = 70;
const WARM = 40;
const item = $input.first().json;
const signup = $("Read the signup").first().json;
const v = (item.output && typeof item.output === "object") ? item.output : {};
const score = Math.max(0, Math.min(100, Math.round(Number(v.fit_score) || 0)));
const tier = score >= HOT ? "hot" : score >= WARM ? "warm" : "cold";
const cost = agentCost(item);
const who = [v.full_name || signup.name || signup.email, v.title, v.company].filter(Boolean).join(", ");
const text = `*New ${tier} signup* (${score}/100): ${who}\n${signup.email}${v.company_size ? ` · ${v.company_size}` : ""}${v.industry ? ` · ${v.industry}` : ""}\n${v.reason || ""}\n_data cost $${cost.looot_cost_usd.toFixed(4)}_`;
return [{ json: { ...signup, ...v, fit_score: score, tier, hot: tier === "hot", text, ...cost } }];
